import { normalizeHeadword } from '@lexpad/core';

/**
 * The longest headword a word may have: the API contract's
 * `WordCore.headword` maxLength. A suggestion longer than that could not be
 * saved as a headword, so it is not offered.
 */
export const MAX_HEADWORD_CHARS = 200;

/**
 * The spelling the model suggests for what the learner typed, or undefined
 * when there is nothing to ask: no suggestion, the same word once
 * normalised, blank, longer than a headword may be, or holding a control
 * character. The suggestion comes from the server, so it is checked here
 * before it is shown and before it can become a headword.
 */
export function suggestedSpelling(headword: string, correction: string | undefined): string | undefined {
  const suggestion = correction?.trim() ?? '';
  if (suggestion === '' || [...suggestion].length > MAX_HEADWORD_CHARS) return undefined;
  // eslint-disable-next-line no-control-regex -- refusing control characters is the point
  if (/[\u0000-\u001f\u007f-\u009f‪-‮⁦-⁩]/u.test(suggestion)) return undefined;
  if (normalizeHeadword(suggestion) === normalizeHeadword(headword)) return undefined;
  return suggestion;
}
